changeSet.sql:
UPDATE parser SET notes = TRIM(REPLACE(IFNULL(notes, ''), '[DONNÉES LOCALES FIGÉES - À MIGRER VERS CRAWLER RÉSEAU]', '')) WHERE dataset_name IN ('es_pep_unions');
UPDATE parser SET notes = CONCAT('[SOURCE EXTERNE LUE À CHAQUE EXÉCUTION] ', IFNULL(notes, '')) WHERE dataset_name IN ('es_pep_unions');
UPDATE pep_function_parser SET completeness = 'PARTIAL', gaps = 'Source officielle lue en direct ; la page ne publie qu''une partie des personnes visées (hauts responsables seulement)' WHERE parser_id IN (SELECT id FROM parser WHERE dataset_name IN ('es_pep_unions'));
